let LANG = 'en';

function t(key) {
  if (LANG === 'zh') return ZH[key] || EN[key] || key;
  return EN[key] || key; // 英文为源：EN 表就是界面文案；没登记的原样返回
}

function tr(en, key) {
  if (LANG === 'zh') return ZH[key || en] || EN[key || en] || en;
  return EN[key || en] || en;
}

function applyI18n(root) {
  (root || document).querySelectorAll('[data-i18n]').forEach(el => {
    el.textContent = t(el.getAttribute('data-i18n'));
  });
  (root || document).querySelectorAll('[data-i18n-title]').forEach(el => {
    el.title = t(el.getAttribute('data-i18n-title'));
  });
  document.documentElement.lang = LANG === 'zh' ? 'zh-CN' : 'en';
  const bn = document.getElementById('brandName');
  if (bn) bn.textContent = t('brand');
  document.title = t('brand');
}

function setLang(lang) {
  LANG = lang === 'zh' ? 'zh' : 'en';
  try { localStorage.setItem('fb_lang', LANG); } catch (e) {}
  applyI18n();
  if (window.go && window.go.app && window.go.app.App) window.go.app.App.SetLang(LANG);
}

function getLang() {
  try { return localStorage.getItem('fb_lang') === 'zh' ? 'zh' : 'en'; } catch (e) { return 'en'; }
}
